    vectorRecallDescription: 'Ajoute une correspondance sémantique en plus de la formulation, de sorte qu\'une mémoire s\'estompe après que l\'utilisateur ait re-phrasé le sujet — et que la plupart des souvenirs soient re-phrasés. Il coûte un appel de vectorisation par tour, et revient à la correspondance de libellé seulement sur timeout.',
    embeddingModelLabel: 'Modèle de vectorisation de la mémoire',
    embeddingModelDescription: 'Le rappel sémantique utilise ce modèle, indépendamment des modèles de vectorisation associés aux bases de connaissances. Laissez vide pour limiter la recherche aux correspondances textuelles. Après une modification, les nouveaux souvenirs utilisent immédiatement le nouveau modèle ; les souvenirs existants restent accessibles par recherche textuelle jusqu’à leur nouvelle vectorisation.',
    conditioningLabel: 'Laissez la recherche de la forme de mémoire',
    conditioningDescription: 'La mémoire participe à la reformulation des requêtes et au classement des documents, en plus d’enrichir les instructions de réponse. Elle contribue ainsi à la qualité de la recherche dans les bases de connaissances.',
    interestThresholdLabel: 'Questions avant qu\'un sujet ne devienne un intérêt',
